-export function calcularFactura(items) {
+// RF-006: con { descuentoGlobal } (entero 0–100) se descuenta sobre el subtotal antes de calcular IVA y neto.
+export function calcularFactura(items, { descuentoGlobal } = {}) {
   if (!Array.isArray(items) || items.length === 0) throw new Error("Una factura necesita al menos una línea");
-  let totalCentavos = 0;
+  const conDescuento = descuentoGlobal !== undefined;
+  if (conDescuento && (!Number.isInteger(descuentoGlobal) || descuentoGlobal < 0 || descuentoGlobal > 100))
+    throw new RangeError("Descuento global inválido: debe ser un entero entre 0 y 100");
+  let subtotalCentavos = 0;
   for (const item of items) {
     if (!Number.isInteger(item.cantidad) || item.cantidad <= 0) throw new RangeError("Cantidad inválida");
     if (!Number.isInteger(item.precioUnitarioCentavos) || item.precioUnitarioCentavos < 0)
       throw new RangeError("Precio inválido: debe estar en centavos enteros");
-    totalCentavos += item.cantidad * item.precioUnitarioCentavos;
+    subtotalCentavos += item.cantidad * item.precioUnitarioCentavos;
   }
+  const descuentoGlobalCentavos = conDescuento ? Math.round((subtotalCentavos * descuentoGlobal) / 100) : 0;
+  const totalCentavos = subtotalCentavos - descuentoGlobalCentavos;
   const ivaCentavos = Math.round(totalCentavos * TASA_IVA);
-  return { totalCentavos, ivaCentavos, netoCentavos: totalCentavos - ivaCentavos };
+  const resultado = { totalCentavos, ivaCentavos, netoCentavos: totalCentavos - ivaCentavos };
+  return conDescuento ? { subtotalCentavos, descuentoGlobalCentavos, ...resultado } : resultado;
 }

 // RF-001, RF-003: emite una factura válida y congelada.
diff --git a/tests/factura.test.mjs b/tests/factura.test.mjs
index fabcb45..5f98078 100644
--- a/tests/factura.test.mjs
+++ b/tests/factura.test.mjs
@@ -30,6 +30,69 @@ test("RF-003: una factura emitida no se puede modificar", () => {
   assert.throws(() => { "use strict"; f.totalCentavos = 1; }, TypeError);
 });

+const LINEAS = [
+  { cantidad: 2, precioUnitarioCentavos: 5000 },
+  { cantidad: 1, precioUnitarioCentavos: 1050 },
+];
+
+test("RF-006: sin parámetro, todo igual que hoy", () => {
+  assert.deepEqual(calcularFactura(LINEAS), { totalCentavos: 11050, ivaCentavos: 1437, netoCentavos: 9613 });
+});
+
+test("RF-006: 10 % global recalcula IVA y neto sobre el total descontado", () => {
+  assert.deepEqual(calcularFactura(LINEAS, { descuentoGlobal: 10 }), {
+    subtotalCentavos: 11050,
+    descuentoGlobalCentavos: 1105,
+    totalCentavos: 9945,
+    ivaCentavos: 1293,
+    netoCentavos: 8652,
+  });
+});
+
+test("RF-006: el descuento se redondea al centavo", () => {
+  const f = calcularFactura(LINEAS, { descuentoGlobal: 5 });
+  assert.equal(f.descuentoGlobalCentavos, 553);
+  assert.equal(f.totalCentavos, 10497);
+});
+
+test("RF-006: 0 % y 100 %", () => {
+  assert.deepEqual(calcularFactura(LINEAS, { descuentoGlobal: 0 }), {
+    subtotalCentavos: 11050,
+    descuentoGlobalCentavos: 0,
+    totalCentavos: 11050,
+    ivaCentavos: 1437,
+    netoCentavos: 9613,
+  });
+  assert.deepEqual(calcularFactura(LINEAS, { descuentoGlobal: 100 }), {
+    subtotalCentavos: 11050,
+    descuentoGlobalCentavos: 11050,
+    totalCentavos: 0,
+    ivaCentavos: 0,
+    netoCentavos: 0,
+  });
+});
+
+test("RF-006: descuento inválido lanza RangeError", () => {
+  for (const descuentoGlobal of [-1, 101, 10.5, "10", null, NaN]) {
+    assert.throws(() => calcularFactura(LINEAS, { descuentoGlobal }), RangeError, String(descuentoGlobal));
+  }
+});
+
+test("RF-006: opciones sin descuento equivalen a sin segundo parámetro", () => {
+  assert.deepEqual(calcularFactura(LINEAS, {}), calcularFactura(LINEAS));
+  assert.deepEqual(calcularFactura(LINEAS, { descuentoGlobal: undefined }), calcularFactura(LINEAS));
+});
+
+test("RF-006: emitirFactura no cambia", () => {
+  const f = emitirFactura({ numero: 1, nit: "1023456", razonSocial: "Cliente SA", items: LINEAS });
+  assert.equal(f.estado, "emitida");
+  assert.ok(Object.isFrozen(f));
+  assert.equal(f.totalCentavos, 11050);
+  assert.equal(f.ivaCentavos, 1437);
+  assert.equal(f.netoCentavos, 9613);
+  assert.ok(!("subtotalCentavos" in f) && !("descuentoGlobalCentavos" in f));
+});
+
